//! Client-only true blueprint execution helpers. Never preload a PASS or Task.
use crate::support::*;
pub const FAMILY:[u8;32]=[160,43,204,72,38,231,208,253,243,141,12,162,12,38,137,129,71,231,26,176,41,238,246,151,54,121,0,16,247,147,245,254];
pub const RENT:u64=100_000_000;
pub fn named(name:&[u8])->Pubkey{Pubkey::find_program_address(&[b"bio",name,&FAMILY],&PROGRAM).0}
pub fn verify_address()->Pubkey{Pubkey::find_program_address(&[b"bio",b"verify",BOOT.as_ref()],&PROGRAM).0}
pub fn disclosure(design:&[u8;32])->Pubkey{let id=hash(8,&[&domain(),design]);Pubkey::find_program_address(&[b"bio",b"disclosure",&id],&PROGRAM).0}
pub fn seed(design:&[u8;32])->Pubkey{Pubkey::find_program_address(&[b"bio",b"seed",&FAMILY,design],&PROGRAM).0}
pub fn knowledge(index:u64)->Pubkey{Pubkey::find_program_address(&[b"bio",b"knowledge",&FAMILY,&index.to_le_bytes()],&PROGRAM).0}
pub fn round(number:u64)->Pubkey{Pubkey::find_program_address(&[b"bio",b"round",&FAMILY,&1u32.to_le_bytes(),&number.to_le_bytes()],&PROGRAM).0}
pub fn reward_start(a:&[(Pubkey,Account)])->i64{i64::from_le_bytes(account(a,pda(b"econ-config")).data[384..392].try_into().unwrap())}
pub fn bytes(name:&str)->Vec<u8>{
 let requested=name;let name=if name=="candidate-c318.bin"||name=="candidate-c316.bin"{"candidate-c320.bin"}else{name};
 let mut g=std::fs::read(std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(format!("../../../fixtures/graphs/{name}"))).unwrap();
 g[16..48].copy_from_slice(&domain());g[48..80].copy_from_slice(&config_id());g[80..112].copy_from_slice(&catalog());g[112..144].copy_from_slice(&release_constants::RULE_HASH);
 if requested=="candidate-c318.bin"||requested=="candidate-c316.bin"{let mut graph=biolab_kernel::graph::decode_graph(&g).unwrap();for edge in &mut graph.edges{if edge.kind==1{edge.src.role=match edge.dst.role{4=>6,5=>7,12 if requested=="candidate-c316.bin"=>7,13 if requested=="candidate-c316.bin"=>6,_=>edge.src.role};edge.owner=biolab_kernel::graph::lca(biolab_kernel::graph::anchor(edge.src).unwrap(),biolab_kernel::graph::anchor(edge.dst).unwrap()).unwrap();}}graph.edges.sort_unstable_by(biolab_kernel::graph::compare_edges);g=biolab_kernel::graph::encode_graph(&graph).unwrap();}
 let mut body=2_000_000u32.to_le_bytes().to_vec();body.extend_from_slice(&(g.len()as u32).to_le_bytes());body.extend_from_slice(&g);body.push(60);
 for role in 1..=15u8{for primitive in 1..=4{body.extend_from_slice(&[role,primitive,1,0,primitive,if primitive==4{role}else{0}]);}}
 let mut b=b"BIOP7K01".to_vec();b.extend_from_slice(&1u16.to_le_bytes());b.extend_from_slice(&[22,0]);b.extend_from_slice(&(body.len()as u32).to_le_bytes());b.extend_from_slice(&body);b
}
pub fn begin_ix(a:&[(Pubkey,Account)],b:&[u8])->Instruction{
 let id=artifact_id(1002,BOOT,b);let mut p=id.to_vec();p.extend_from_slice(&Sha256::digest(b));p.extend_from_slice(&(b.len()as u32).to_le_bytes());let generation=a.iter().find(|(k,_)|*k==verify_address()).filter(|(_,v)|!v.data.is_empty()).map_or(0,|(_,v)|read64(&v.data,380));p.extend_from_slice(&generation.to_le_bytes());p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new_readonly(artifact_address(&id),false),AccountMeta::new(verify_address(),false)]);Instruction{program_id:PROGRAM,accounts:m,data:wire(30,next_nonce(a,BOOT),&p)}
}
pub fn step_ix(a:&[(Pubkey,Account)],b:&[u8],prior:&[u8])->Instruction{
 let id=artifact_id(1002,BOOT,b);let cursor=u16::from_le_bytes(prior[16..18].try_into().unwrap());let mut p=id.to_vec();p.extend_from_slice(&prior[8..16]);p.extend_from_slice(&cursor.to_le_bytes());p.extend_from_slice(&[((73-cursor).min(2))as u8,0]);p.extend_from_slice(&prior[30..62]);p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new_readonly(artifact_address(&id),false),AccountMeta::new(verify_address(),false)]);Instruction{program_id:PROGRAM,accounts:m,data:wire(31,next_nonce(a,BOOT),&p)}
}
pub fn verify(vm:&Mollusk,a:Vec<(Pubkey,Account)>,b:&[u8])->(Vec<(Pubkey,Account)>,Vec<u8>,u64){
 let(mut a,_)=put_artifact(vm,a,1002,b);add_empty(&mut a,verify_address());let r=vm.process_instruction(&begin_ix(&a,b),&a);println!("ORI_BEGIN cu={} raw={:?}",r.compute_units_consumed,r.raw_result);assert_eq!(r.raw_result,Ok(()));let mut peak=r.compute_units_consumed;a=r.resulting_accounts;let mut prior=r.return_data;
 while u16::from_le_bytes(prior[16..18].try_into().unwrap())<73{let r=vm.process_instruction(&step_ix(&a,b,&prior),&a);if r.raw_result.is_err(){println!("ORI_STEP_FAIL cu={} raw={:?}",r.compute_units_consumed,r.raw_result);}assert_eq!(r.raw_result,Ok(()));peak=peak.max(r.compute_units_consumed);a=r.resulting_accounts;prior=r.return_data;}
 (a,prior,peak)
}
pub fn register_ix(a:&[(Pubkey,Account)],b:&[u8],prior:&[u8])->Instruction{
 let id=artifact_id(1002,BOOT,b);let design:[u8;32]=prior[62..94].try_into().unwrap();let s=seed(&design);let index=a.iter().find(|(k,_)|*k==s).filter(|(_,v)|!v.data.is_empty()).map_or_else(||a.iter().find(|(k,_)|*k==named(b"task")).filter(|(_,v)|!v.data.is_empty()).map_or(0,|(_,v)|read64(&v.data,164)),|(_,v)|read64(&v.data,256));
 let mut p=id.to_vec();p.extend_from_slice(&Sha256::digest(b));p.extend_from_slice(&(b.len()as u32).to_le_bytes());p.extend_from_slice(&prior[8..16]);p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new_readonly(artifact_address(&id),false),AccountMeta::new(verify_address(),false),AccountMeta::new(named(b"task"),false),AccountMeta::new(named(b"opening"),false),AccountMeta::new(s,false),AccountMeta::new(disclosure(&design),false),AccountMeta::new(knowledge(index),false),AccountMeta::new(named(b"k-slot"),false)]);Instruction{program_id:PROGRAM,accounts:m,data:wire(32,next_nonce(a,BOOT),&p)}
}
pub fn prepare_register(a:&mut Vec<(Pubkey,Account)>,prior:&[u8]){let design:[u8;32]=prior[62..94].try_into().unwrap();let index=a.iter().find(|(k,_)|*k==named(b"task")).filter(|(_,v)|!v.data.is_empty()).map_or(0,|(_,v)|read64(&v.data,164));for k in[named(b"task"),named(b"opening"),seed(&design),disclosure(&design),knowledge(index),named(b"k-slot")]{add_empty(a,k);}}
pub fn register(vm:&Mollusk,mut a:Vec<(Pubkey,Account)>,b:&[u8],prior:&[u8])->(Vec<(Pubkey,Account)>,Vec<u8>,u64){prepare_register(&mut a,prior);let r=vm.process_instruction(&register_ix(&a,b,prior),&a);println!("ORI_REGISTER cu={} C={} raw={:?}",r.compute_units_consumed,read64(prior,22),r.raw_result);assert_eq!(r.raw_result,Ok(()));(r.resulting_accounts,r.return_data,r.compute_units_consumed)}
pub fn seal_ix(a:&[(Pubkey,Account)],max:u8)->Instruction{let od=&account(a,named(b"opening")).data;let cursor=read64(od,194);let count=read64(od,184);let stop=(cursor+u64::from(max)).min(count);let mut p=cursor.to_le_bytes().to_vec();p.push(max);p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new(named(b"task"),false),AccountMeta::new(named(b"opening"),false),AccountMeta::new(named(b"seed-final"),false)]);for i in cursor..stop{let d=&account(a,knowledge(i)).data;let design:[u8;32]=d[164..196].try_into().unwrap();m.extend([AccountMeta::new_readonly(knowledge(i),false),AccountMeta::new_readonly(seed(&design),false)]);}Instruction{program_id:PROGRAM,accounts:m,data:wire(33,next_nonce(a,BOOT),&p)}}
pub fn prewarm(vm:&Mollusk,mut a:Vec<(Pubkey,Account)>)->(Vec<(Pubkey,Account)>,u64){let mut peak=0;for n in 0..initial_count(){let file=if n<12{format!("seed-{n:02}.bin")}else{format!("candidate-c{}.bin",[324,320,318,316][n-12])};let b=bytes(&file);let(next,prior,cu)=verify(vm,a,&b);peak=peak.max(cu);let(next,_,cu)=register(vm,next,&b,&prior);peak=peak.max(cu);
 let dir=std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../evidence");let file=dir.join(format!("native-blueprint-{n:02}.bin"));std::fs::write(&file,&b).unwrap();let artifact=artifact_id(1002,BOOT,&b);let out=std::process::Command::new("node").arg(std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tools/originality-golden.mjs")).arg("verify").arg(&file).arg(hex(&artifact)).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let golden=String::from_utf8(out.stdout).unwrap();let index=read64(&account(&next,seed(&prior[62..94].try_into().unwrap())).data,256);let k=&account(&next,knowledge(index)).data;assert!(golden.contains(&format!("\"design\":\"{}\"",hex(&prior[62..94]))));assert!(golden.contains(&format!("\"h16\":\"{}\"",hex(&k[333..365]))));println!("ORI_NODE_GOLDEN {golden}");a=next;}(a,peak)}

pub fn round_id(n:u64)->[u8;32]{hash(9,&[&domain(),&FAMILY,&1u32.to_le_bytes(),&n.to_le_bytes()])}
pub fn commit_address(id:&[u8;32])->Pubkey{Pubkey::find_program_address(&[b"bio",b"commit",id],&PROGRAM).0}
pub fn commit_hash(round:u64,author:Pubkey,design:&[u8;32],manufacture_nonce:u64,salt:&[u8;32])->[u8;32]{let mut op=[0;32];op[..8].copy_from_slice(&manufacture_nonce.to_le_bytes());hash(22,&[&domain(),&FAMILY,&1u32.to_le_bytes(),&round.to_le_bytes(),author.as_ref(),design,&op,salt])}
pub fn commit_ix(a:&[(Pubkey,Account)],round_number:u64,hidden:&[u8;32])->Instruction{let n=next_nonce(a,BOOT);let id=business_for(BOOT,n);let mut p=FAMILY.to_vec();p.extend_from_slice(&1u32.to_le_bytes());p.extend_from_slice(&round_number.to_le_bytes());p.extend_from_slice(hidden);p.extend_from_slice(BOOT.as_ref());p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new(named(b"task"),false),AccountMeta::new(named(b"k-slot"),false),AccountMeta::new_readonly(named(b"seed-final"),false),AccountMeta::new(round(round_number),false),AccountMeta::new(commit_address(&id),false)]);Instruction{program_id:PROGRAM,accounts:m,data:wire(34,n,&p)}}
pub fn final_step_ix(a:&[(Pubkey,Account)],n:u64,max:u8)->Instruction{let r=account(a,round(n));let(phase,cc,kc)=if r.data.is_empty(){(0,0,0)}else{let b=&r.data[120..];if b[117]==0||read64(b,118)!=read64(&account(a,named(b"task")).data,239){(b[117],0,0)}else{(b[117],read64(b,175),read64(b,if b[117]==1{126}else{183}))}};let mut p=FAMILY.to_vec();p.extend_from_slice(&1u32.to_le_bytes());p.extend_from_slice(&n.to_le_bytes());p.push(phase);p.extend_from_slice(&cc.to_le_bytes());p.extend_from_slice(&kc.to_le_bytes());p.push(max);p.extend_from_slice(BOOT.as_ref());p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new(named(b"task"),false),AccountMeta::new(named(b"k-slot"),false),AccountMeta::new(round(n),false)]);if phase==1{let stop=(kc+u64::from(max)).min(if r.data.len()==509{read64(&r.data,501)}else{read64(&r.data,205)});for i in kc..stop{m.push(AccountMeta::new_readonly(knowledge(i),false));let row=&account(a,knowledge(i)).data;if row[365]==0&&row[268]==2{let key=Pubkey::new_from_array(row[269..301].try_into().unwrap());if !m.iter().any(|meta|meta.pubkey==key){m.push(AccountMeta::new_readonly(key,false));}}}}Instruction{program_id:PROGRAM,accounts:m,data:wire(35,next_nonce(a,BOOT),&p)}}

pub fn hex(b:&[u8])->String{b.iter().map(|x|format!("{x:02x}")).collect()}

pub fn safety(epoch:u64)->Pubkey{Pubkey::find_program_address(&[b"bio",b"task-safety",&FAMILY,&epoch.to_le_bytes()],&PROGRAM).0}
pub fn seed_id(design:&[u8;32])->[u8;32]{hash(15,&[&[1],&domain(),&FAMILY,design])}
pub fn history_begin_ix(a:&[(Pubkey,Account)],b:&[u8],design:&[u8;32])->Instruction{
 let id=artifact_id(1002,BOOT,b);let mut p=vec![0];p.extend_from_slice(&seed_id(design));p.extend_from_slice(&id);p.extend_from_slice(&Sha256::digest(b));p.extend_from_slice(&(b.len()as u32).to_le_bytes());p.extend_from_slice(&read64(&account(a,verify_address()).data,380).to_le_bytes());p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new_readonly(artifact_address(&id),false),AccountMeta::new(verify_address(),false),AccountMeta::new_readonly(seed(design),false)]);Instruction{program_id:PROGRAM,accounts:m,data:wire(37,next_nonce(a,BOOT),&p)}
}
pub fn history(vm:&Mollusk,a:Vec<(Pubkey,Account)>,b:&[u8],design:&[u8;32])->(Vec<(Pubkey,Account)>,Vec<u8>,u64){let begin=vm.process_instruction(&history_begin_ix(&a,b,design),&a);println!("ORI_HISTORY_BEGIN cu={} raw={:?}",begin.compute_units_consumed,begin.raw_result);assert_eq!(begin.raw_result,Ok(()));let mut a=begin.resulting_accounts;let mut prior=begin.return_data;let mut peak=begin.compute_units_consumed;let mut steps=0;while read_failure(&prior)==0&&u16::from_le_bytes(prior[16..18].try_into().unwrap())<73{let r=vm.process_instruction(&step_ix(&a,b,&prior),&a);assert_eq!(r.raw_result,Ok(()));a=r.resulting_accounts;prior=r.return_data;peak=peak.max(r.compute_units_consumed);steps+=1;assert!(steps<50);}println!("ORI_HISTORY_DONE rounds={} failure={} stage={} peak={peak}",u16::from_le_bytes(prior[16..18].try_into().unwrap()),read_failure(&prior),prior[130]);(a,prior,peak)}
pub fn read_failure(prior:&[u8])->u32{u32::from_le_bytes(prior[126..130].try_into().unwrap())}
pub fn prove_ix(a:&[(Pubkey,Account)],b:&[u8],prior:&[u8],design:&[u8;32],index:u64)->Instruction{let epoch=read64(&account(a,named(b"task")).data,239);let id=artifact_id(1002,BOOT,b);let mut p=FAMILY.to_vec();p.extend_from_slice(&1u32.to_le_bytes());p.extend_from_slice(&index.to_le_bytes());p.extend_from_slice(&epoch.to_le_bytes());p.extend_from_slice(&id);p.extend_from_slice(&Sha256::digest(b));p.extend_from_slice(&(b.len()as u32).to_le_bytes());p.extend_from_slice(BOOT.as_ref());p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new(named(b"task"),false),AccountMeta::new(named(b"k-slot"),false),AccountMeta::new(pda(b"mining"),false),AccountMeta::new(knowledge(index),false),AccountMeta::new_readonly(artifact_address(&id),false),AccountMeta::new_readonly(verify_address(),false),AccountMeta::new_readonly(seed(design),false),AccountMeta::new(safety(epoch+1),false),AccountMeta::new(round(((i64::from_le_bytes(account(a,CLOCK).data[32..40].try_into().unwrap())-reward_start(a))/259200)as u64),false)]);if read_failure(prior)==0&&u32::from_le_bytes(prior[18..22].try_into().unwrap())==2_000_000&&read64(prior,22)>0{let count=read64(&account(a,named(b"task")).data,164);m.extend([AccountMeta::new(knowledge(count),false),AccountMeta::new(disclosure(&prior[62..94].try_into().unwrap()),false)]);}Instruction{program_id:PROGRAM,accounts:m,data:wire(38,next_nonce(a,BOOT),&p)}}
pub fn prepare_proof(a:&mut Vec<(Pubkey,Account)>,prior:&[u8]){let epoch=read64(&account(a,named(b"task")).data,239);for key in[pda(b"mining"),safety(epoch+1),round(((i64::from_le_bytes(account(a,CLOCK).data[32..40].try_into().unwrap())-reward_start(a))/259200)as u64)]{add_empty(a,key);}if read_failure(prior)==0&&read64(prior,22)>0{let count=read64(&account(a,named(b"task")).data,164);add_empty(a,knowledge(count));add_empty(a,disclosure(&prior[62..94].try_into().unwrap()));}}
pub fn audit_ix(a:&[(Pubkey,Account)],b:&[u8],design:&[u8;32])->Instruction{let epoch=read64(&account(a,named(b"task")).data,239);let current=safety(epoch);let cursor=read64(&account(a,current).data,326);let k=&account(a,knowledge(cursor)).data;let mut p=FAMILY.to_vec();p.extend_from_slice(&1u32.to_le_bytes());p.extend_from_slice(&epoch.to_le_bytes());p.extend_from_slice(&cursor.to_le_bytes());p.extend_from_slice(BOOT.as_ref());p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new(named(b"task"),false),AccountMeta::new(named(b"k-slot"),false),AccountMeta::new(pda(b"mining"),false),AccountMeta::new(current,false),AccountMeta::new_readonly(knowledge(cursor),false)]);if k[365]==1{let proof=Pubkey::new_from_array(k[367..399].try_into().unwrap());if proof!=current{m.push(AccountMeta::new_readonly(proof,false));}}else{m.extend([AccountMeta::new_readonly(verify_address(),false),AccountMeta::new_readonly(artifact_address(&artifact_id(1002,BOOT,b)),false),AccountMeta::new_readonly(seed(design),false),AccountMeta::new_readonly(disclosure(design),false)]);if k[268]==2{let proof=Pubkey::new_from_array(k[269..301].try_into().unwrap());if proof!=current{m.push(AccountMeta::new_readonly(proof,false));}}}Instruction{program_id:PROGRAM,accounts:m,data:wire(39,next_nonce(a,BOOT),&p)}}
pub fn recover_ix(a:&[(Pubkey,Account)],expected:u64)->Instruction{let epoch=read64(&account(a,named(b"task")).data,239);let mut p=FAMILY.to_vec();p.extend_from_slice(&1u32.to_le_bytes());p.extend_from_slice(&epoch.to_le_bytes());p.extend_from_slice(&expected.to_le_bytes());p.extend_from_slice(BOOT.as_ref());p.extend_from_slice(&RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new(named(b"task"),false),AccountMeta::new(named(b"k-slot"),false),AccountMeta::new(pda(b"mining"),false),AccountMeta::new(safety(epoch),false)]);Instruction{program_id:PROGRAM,accounts:m,data:wire(40,next_nonce(a,BOOT),&p)}}
